import java.util.Queue;

public class MakeColumnQueueTests {

    private TextHelpAppendable textHelpAppendable;
    private TextStyle textStyle;

    @BeforeEach
    public void setUp() {
        textHelpAppendable = new TextHelpAppendable(new StringBuilder());
        textStyle = TextStyle.builder()
                .setMaxWidth(TextHelpAppendable.DEFAULT_WIDTH)
                .setLeftPad(TextHelpAppendable.DEFAULT_LEFT_PAD)
                .setIndent(TextHelpAppendable.DEFAULT_INDENT)
                .create(); // Fixed: Changed `build()` to `create()` based on the error message
    }

    @Test
    public void test_makeColumnQueue_withValidData() {
        CharSequence columnData = "This is a sample text that should be wrapped according to the specified style.";
        Queue<String> result = textHelpAppendable.makeColumnQueue(columnData, textStyle);

        assertNotNull(result);
        assertFalse(result.isEmpty());
        for (String line : result) {
            assertTrue(line.length() <= textStyle.getMaxWidth());
            assertTrue(line.startsWith(generatePadding(textStyle.getLeftPad() + textStyle.getIndent())));
        }
    }

    @Test
    public void test_makeColumnQueue_withEmptyData() {
        CharSequence columnData = "";
        Queue<String> result = textHelpAppendable.makeColumnQueue(columnData, textStyle);

        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    public void test_makeColumnQueue_withSingleWordExceedingMaxWidth() {
        CharSequence columnData = "Supercalifragilisticexpialidocious";
        Queue<String> result = textHelpAppendable.makeColumnQueue(columnData, textStyle);

        assertNotNull(result);
        assertFalse(result.isEmpty());
        assertEquals(1, result.size());
        assertEquals(generatePadding(textStyle.getLeftPad() + textStyle.getIndent()) + columnData, result.peek());
    }

    @Test
    public void test_makeColumnQueue_withWhitespaceHandling() {
        CharSequence columnData = "   Leading and trailing spaces should be handled properly.   ";
        Queue<String> result = textHelpAppendable.makeColumnQueue(columnData, textStyle);

        assertNotNull(result);
        assertFalse(result.isEmpty());
        for (String line : result) {
            assertTrue(line.length() <= textStyle.getMaxWidth());
            assertTrue(line.startsWith(generatePadding(textStyle.getLeftPad() + textStyle.getIndent())));
        }
    }

    @Test
    public void test_makeColumnQueue_withMultipleParagraphs() {
        CharSequence columnData = "Paragraph one.\n\nParagraph two.";
        Queue<String> result = textHelpAppendable.makeColumnQueue(columnData, textStyle);

        assertNotNull(result);
        assertFalse(result.isEmpty());
        assertEquals(2, result.size());
        for (String line : result) {
            assertTrue(line.length() <= textStyle.getMaxWidth());
            assertTrue(line.startsWith(generatePadding(textStyle.getLeftPad() + textStyle.getIndent())));
        }
    }

    private String generatePadding(int length) {
        StringBuilder padding = new StringBuilder();
        for (int i = 0; i < length; i++) {
            padding.append(" ");
        }
        return padding.toString();
    }
}

